`getLeaveSessionOptionsForCourse`（同一檔，緊接在 `leaveForm` 之後）：

```1298:1316:/home/admin/frontend/src/pages/CourseManagement.vue
const getLeaveSessionOptionsForCourse = (course) => {
  const cid = String(course?.id ?? '');
  const rows = classSessionsByCourse.value[cid];
  if (!Array.isArray(rows) || rows.length === 0) {
    const fallbackDates = sessions(course);
    return fallbackDates.map((date, i) => ({ date, index: i + 1 }));
  }

  const options = [];
  const seenDates = new Set();
  rows.forEach((row, idx) => {
    const status = String(row?.status || '').toLowerCase();
    if (['completed', 'attended', 'late', 'excused', 'absent', 'cancelled', 'leave'].includes(status)) return;
    const date = String(row?.session_date || '').slice(0, 10);
    if (!date || seenDates.has(date)) return;
    seenDates.add(date);
    options.push({ date, index: idx + 1 });
  });
  return options;
};
```

